    Task<FinancialPositionReport> GetFinancialPositionAsync(Guid tenantId, DateTime asOf, CancellationToken ct);
    Task<ProfitLossReport> GetProfitLossAsync(Guid tenantId, DateTime from, DateTime to, CancellationToken ct);
    Task<PaymentPlanSweepResult> RunPaymentPlanSweepAsync(Guid tenantId, DateTime asOf, CancellationToken ct);
    Task<FinancePayrollPosting> ImportAndPostPayrollAsync(Guid tenantId, Guid actorId, ImportFinancePayrollCommand command, CancellationToken ct);
    Task<IReadOnlyList<FinanceBankFeedTransaction>> ImportBankFeedAsync(Guid tenantId, ImportFinanceBankFeedCommand command, CancellationToken ct);
    Task<FinanceGrant> CreateGrantAsync(Guid tenantId, CreateFinanceGrantCommand command, CancellationToken ct);
    Task<FinanceGrant> RecordGrantReceiptAsync(Guid tenantId, Guid actorId, RecordFinanceGrantReceiptCommand command, CancellationToken ct);
    Task<FinanceScholarshipAward> AwardScholarshipAsync(Guid tenantId, Guid actorId, AwardFinanceScholarshipCommand command, CancellationToken ct);
    Task<FinanceUtilityBill> CreateUtilityBillAsync(Guid tenantId, CreateFinanceUtilityBillCommand command, CancellationToken ct);
    Task<FinanceUtilityBill> ApproveUtilityBillAsync(Guid tenantId, Guid actorId, Guid billId, CancellationToken ct);
