    Task<FinanceInventoryMovement> ReceiveInventoryAsync(Guid tenantId, Guid actorId, ReceiveFinanceInventoryCommand command, CancellationToken ct);
    Task<FinanceInventoryMovement> IssueInventoryAsync(Guid tenantId, Guid actorId, IssueFinanceInventoryCommand command, CancellationToken ct);
    Task<FinanceInventoryMovement> CountInventoryAsync(Guid tenantId, Guid actorId, CountFinanceInventoryCommand command, CancellationToken ct);
    Task<FinanceFleetCostPosting> PostFleetCostAsync(Guid tenantId, Guid actorId, PostFinanceFleetCostCommand command, CancellationToken ct);
